deepml vfx 0.3
module corpus.deepml_vfx.example_04751
policy deterministic
policy no_network
effect Effect04751 {
  coupled simulation PortalSim seed 4751 { fluid: Energy cloth: Veil particles: Sparks }
  procedural operator Distort(time, portal_state) differentiable
  cache PortalCache10 interval 0s..10s step 1/60s hash sha256("cache:04751")
  bind scene PortalScene8
  bind timeline PortalSequence6
  render_graph { Sim -> Lighting -> Distortion -> Composite }
  composite multipass [SceneColor, PortalGlow, Distortion, Atmosphere]
}

